package com.giftplatform.localization;

import com.giftplatform.security.ActorContext;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import java.util.*;

@RestController
@RequestMapping("/api/admin/localization")
public class LocalizationAdminController {
    private final JdbcTemplate db;private final ActorContext actor;private final LocalizationService service;
    public LocalizationAdminController(JdbcTemplate db,ActorContext actor,LocalizationService service){this.db=db;this.actor=actor;this.service=service;}
    private UUID admin(){if(!actor.isPlatformAdmin())throw new ResponseStatusException(HttpStatus.FORBIDDEN);return actor.requireAuthenticatedUserId();}
    private void audit(String action,UUID target){db.update("INSERT INTO platform_admin_action_audit(id,actor_id,action,target_id,module_code) VALUES(?,?,?,?,?)",UUID.randomUUID(),admin(),action,target,"LOCALIZATION");}
    public record Configuration(@NotNull Boolean enabled,@NotBlank @Size(max=63) String defaultLanguage,@NotBlank @Size(max=63) String fallbackLanguage,@Min(0) long version){}
    public record LanguageInput(@NotBlank @Size(max=120) String nativeName,@NotBlank @Size(max=120) String englishName,@Pattern(regexp="LTR|RTL") @NotNull String direction,@NotNull Boolean enabled,@Min(0) long version){}
    public record Translation(@NotNull @Size(max=10000) String text,@NotNull Boolean published,@Min(0) long version){}
    public record Scope(@NotNull @Pattern(regexp="INHERIT|ENABLED|DISABLED") String state){}
    @GetMapping public Map<String,Object> settings(){admin();return Map.of("settings",service.settings(),"languages",service.languages(false));}
    @PutMapping @Transactional
    public LocalizationService.Settings configure(@Valid @RequestBody Configuration input){admin();long version=db.queryForObject("SELECT version FROM platform_localization_settings WHERE id=1 FOR UPDATE",Long.class);if(version!=input.version())throw conflict();
        for(String code:List.of(input.defaultLanguage(),input.fallbackLanguage()))if(service.languages(true).stream().noneMatch(l->l.code().equals(code)))throw bad("Default and fallback languages must be enabled");
        db.update("UPDATE platform_localization_settings SET enabled=?,default_language=?,fallback_language=?,version=version+1,changed_by=?,changed_at=now() WHERE id=1",input.enabled(),input.defaultLanguage(),input.fallbackLanguage(),admin());audit("LOCALIZATION_CONFIGURATION_CHANGED",null);return service.settings();}
    @PutMapping("/languages/{code}") @Transactional
    public List<LocalizationService.Language> language(@PathVariable String code,@Valid @RequestBody LanguageInput input){admin();db.queryForObject("SELECT version FROM platform_localization_settings WHERE id=1 FOR UPDATE",Long.class);if(code.equalsIgnoreCase("cimode")||code.length()>63||!code.matches("[A-Za-z]{2,8}(-[A-Za-z0-9]{2,8})*")||!canonical(code))throw bad("Use a canonical BCP 47 language code");
        var current=db.query("SELECT version FROM platform_languages WHERE code=?",(rs,i)->rs.getLong(1),code);long version=current.isEmpty()?0:current.get(0);if(version!=input.version())throw conflict();var config=service.settings();if(!input.enabled()&&(code.equals(config.defaultLanguage())||code.equals(config.fallbackLanguage())))throw bad("Choose another default/fallback language before disabling this one");
        db.update("INSERT INTO platform_languages(code,native_name,english_name,direction,enabled,version,changed_by) VALUES(?,?,?,?,?,1,?) ON CONFLICT(code) DO UPDATE SET native_name=EXCLUDED.native_name,english_name=EXCLUDED.english_name,direction=EXCLUDED.direction,enabled=EXCLUDED.enabled,version=platform_languages.version+1,changed_by=EXCLUDED.changed_by,changed_at=now()",code,input.nativeName().strip(),input.englishName().strip(),input.direction(),input.enabled(),admin());audit("LOCALIZATION_LANGUAGE_CHANGED",null);return service.languages(false);}
    @GetMapping("/translations")
    public Map<String,Object> translations(@RequestParam String language,@RequestParam(defaultValue="") String search,@RequestParam(defaultValue="0") int offset,@RequestParam(defaultValue="50") int limit){admin();if(!service.settings().enabled())throw new ResponseStatusException(HttpStatus.CONFLICT,"Enable multi-language support to manage translations");if(language.length()>63||search.length()>200||offset<0||offset>100000||limit<1||limit>100)throw bad("Invalid translation page");String query="%"+search.strip()+"%";var rows=db.queryForList("SELECT s.message_key,s.source_text,s.category,t.translated_text,COALESCE(t.published,FALSE) AS published,COALESCE(t.version,0) AS version FROM localization_sources s LEFT JOIN localization_translations t ON t.message_key=s.message_key AND t.language_code=? WHERE s.source_text ILIKE ? OR s.message_key ILIKE ? ORDER BY s.message_key LIMIT ? OFFSET ?",language,query,query,limit,offset);return Map.of("entries",rows,"sourceCount",db.queryForObject("SELECT count(*) FROM localization_sources",Long.class),"publishedCount",db.queryForObject("SELECT count(*) FROM localization_translations WHERE language_code=? AND published",Long.class,language));}
    @PutMapping("/translations/{language}/{key}") @Transactional
    public Map<String,Object> translation(@PathVariable String language,@PathVariable String key,@Valid @RequestBody Translation input){admin();if(!service.settings().enabled())throw new ResponseStatusException(HttpStatus.CONFLICT,"Multi-language support is disabled");if(language.length()>63||key.length()>120)throw bad("Invalid translation key");
        String source=db.query("SELECT source_text FROM localization_sources WHERE message_key=?",(rs,i)->rs.getString(1),key).stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));
        if(!LocalizationService.placeholders(source).equals(LocalizationService.placeholders(input.text())))throw bad("Translation must preserve every named placeholder");
        db.queryForObject("SELECT version FROM platform_localization_settings WHERE id=1 FOR UPDATE",Long.class);var versions=db.query("SELECT version FROM localization_translations WHERE language_code=? AND message_key=?",(rs,i)->rs.getLong(1),language,key);long version=versions.isEmpty()?0:versions.get(0);if(version!=input.version())throw conflict();
        if(!Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM platform_languages WHERE code=?)",Boolean.class,language)))throw bad("Unknown language");
        db.update("INSERT INTO localization_translations(language_code,message_key,translated_text,published,version,changed_by) VALUES(?,?,?,?,1,?) ON CONFLICT(language_code,message_key) DO UPDATE SET translated_text=EXCLUDED.translated_text,published=EXCLUDED.published,version=localization_translations.version+1,changed_by=EXCLUDED.changed_by,changed_at=now()",language,key,input.text(),input.published(),admin());audit("LOCALIZATION_TRANSLATION_CHANGED",null);return Map.of("version",version+1,"published",input.published());}
    public record ImportBatch(@NotNull @Size(max=2000) Map<String,Translation> entries,@NotNull Boolean publish){}
    @GetMapping("/translations/{language}/export")
    public Map<String,Object> export(@PathVariable String language){admin();if(!service.settings().enabled())throw new ResponseStatusException(HttpStatus.CONFLICT,"Multi-language support is disabled");if(language.length()>63)throw bad("Invalid language");Map<String,Object> result=new LinkedHashMap<>();db.query("SELECT s.message_key,s.source_text,COALESCE(t.translated_text,s.source_text) AS text,COALESCE(t.version,0) AS version,COALESCE(t.published,FALSE) AS published FROM localization_sources s LEFT JOIN localization_translations t ON t.message_key=s.message_key AND t.language_code=? ORDER BY s.message_key",(org.springframework.jdbc.core.RowCallbackHandler)rs->{result.put(rs.getString("message_key"),Map.of("source",rs.getString("source_text"),"text",rs.getString("text"),"version",rs.getLong("version"),"published",rs.getBoolean("published")));},language);return result;}
    @PostMapping("/translations/{language}/import") @Transactional
    public Map<String,Object> importBatch(@PathVariable String language,@Valid @RequestBody ImportBatch input){admin();for(var entry:input.entries().entrySet()){Translation value=entry.getValue();if(entry.getKey()==null||value==null||value.text()==null||value.text().length()>10000||value.version()<0)throw bad("Invalid translation import entry");translation(language,entry.getKey(),new Translation(value.text(),input.publish(),value.version()));}return Map.of("imported",input.entries().size(),"published",input.publish());}
    @GetMapping("/scopes/{scope}/{id}") public Map<String,Object> scope(@PathVariable String scope,@PathVariable UUID id){admin();String[] names=scopeNames(scope);validateTarget(names,id);var values=db.query("SELECT enabled FROM "+names[0]+" WHERE "+names[1]+"=?",(rs,i)->rs.getBoolean(1),id);return Map.of("state",values.isEmpty()?"INHERIT":values.get(0)?"ENABLED":"DISABLED");}
    @PutMapping("/scopes/{scope}/{id}") @Transactional
    public Map<String,Object> scope(@PathVariable String scope,@PathVariable UUID id,@Valid @RequestBody Scope input){admin();String[] names=scopeNames(scope);validateTarget(names,id);if(input.state().equals("INHERIT"))db.update("DELETE FROM "+names[0]+" WHERE "+names[1]+"=?",id);else db.update("INSERT INTO "+names[0]+"("+names[1]+",enabled,changed_by) VALUES(?,?,?) ON CONFLICT("+names[1]+") DO UPDATE SET enabled=EXCLUDED.enabled,changed_by=EXCLUDED.changed_by,changed_at=now()",id,input.state().equals("ENABLED"),admin());audit("LOCALIZATION_SCOPE_CHANGED",id);return Map.of("state",input.state());}

    public record DeliveryTemplate(@NotNull @Pattern(regexp="[A-Za-z0-9_-]{1,120}") String templateId,@Min(0) long version){}
    @GetMapping("/delivery-templates") public List<Map<String,Object>> deliveryTemplates(){admin();return db.queryForList("SELECT language_code,provider,template_id,version FROM language_delivery_templates ORDER BY language_code,provider");}
    @PutMapping("/delivery-templates/{language}") @Transactional
    public Map<String,Object> deliveryTemplate(@PathVariable String language,@Valid @RequestBody DeliveryTemplate input){admin();if(language.length()>63||service.languages(false).stream().noneMatch(l->l.code().equals(language)))throw bad("Unknown language");db.queryForObject("SELECT version FROM platform_localization_settings WHERE id=1 FOR UPDATE",Long.class);var versions=db.query("SELECT version FROM language_delivery_templates WHERE language_code=? AND provider='MSG91'",(rs,i)->rs.getLong(1),language);long version=versions.isEmpty()?0:versions.get(0);if(version!=input.version())throw conflict();db.update("INSERT INTO language_delivery_templates(language_code,provider,template_id,version,changed_by) VALUES(?,'MSG91',?,1,?) ON CONFLICT(language_code,provider) DO UPDATE SET template_id=EXCLUDED.template_id,version=language_delivery_templates.version+1,changed_by=EXCLUDED.changed_by,changed_at=now()",language,input.templateId(),admin());audit("LOCALIZATION_SMS_TEMPLATE_CHANGED",null);return Map.of("version",version+1);}

    public record Source(@NotBlank @Size(max=10000) String text){}
    @PostMapping("/sources") @Transactional
    public Map<String,String> source(@Valid @RequestBody Source input){admin();if(!service.settings().enabled())throw new ResponseStatusException(HttpStatus.CONFLICT,"Multi-language support is disabled");LocalizationService.placeholders(input.text());String key=LocalizationService.sourceKey(input.text());db.update("INSERT INTO localization_sources(message_key,source_text,category) VALUES(?,?,'UI') ON CONFLICT(message_key) DO NOTHING",key,input.text());audit("LOCALIZATION_SOURCE_REGISTERED",null);return Map.of("key",key);}
    private boolean canonical(String code){try{return new Locale.Builder().setLanguageTag(code).build().toLanguageTag().equals(code);}catch(IllformedLocaleException ex){return false;}}
    private String[] scopeNames(String scope){return switch(scope){case "HOST"->new String[]{"localization_host_controls","host_id","users"};case "EVENT"->new String[]{"localization_event_controls","event_id","events"};default->throw bad("Unknown localization scope");};}
    private void validateTarget(String[] names,UUID id){if(!Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM "+names[2]+" WHERE id=?)",Boolean.class,id)))throw new ResponseStatusException(HttpStatus.NOT_FOUND);}
    private ResponseStatusException bad(String message){return new ResponseStatusException(HttpStatus.BAD_REQUEST,message);}
    private ResponseStatusException conflict(){return new ResponseStatusException(HttpStatus.CONFLICT,"Language settings changed. Reload before saving");}
}
